/**
 * Turns a legal question into a prompt for one small animated scene.
 *
 * Deliberately minimal: flat vector, one subject, one action, no text. Simple scenes
 * generate in about three seconds, and a legal tool must never let a generated image
 * carry information — the scene depicts the physical activity only, never the legal
 * outcome.
 */

type Body = { match: RegExp; name: string; look: string }

/** The body has to come from the question. A grey Moon standing in for Mars is wrong. */
const BODIES: Body[] = [
  { match: /\bmars|martian\b/i, name: "Mars", look: "a large rust-red planet surface with a dusty salmon sky" },
  { match: /\basteroid|belt|near-earth\b/i, name: "an asteroid", look: "a small dark-grey rocky asteroid tumbling against black space" },
  { match: /\bvenus|venusian\b/i, name: "Venus", look: "a pale yellow cloud-covered planet" },
  { match: /\btitan|europa|enceladus|ganymede\b/i, name: "an icy moon", look: "a pale blue-white icy surface under a dark sky" },
  { match: /\bearth orbit|low earth|leo|geostationary|satellite\b/i, name: "Earth orbit", look: "the blue curve of Earth below, black space above" },
]

const DEFAULT_BODY: Body = {
  match: /./,
  name: "the Moon",
  look: "a large pale grey cratered surface against a dark indigo sky",
}

type Activity = { match: RegExp; action: (body: string) => string }

const ACTIVITIES: Activity[] = [
  {
    match: /\b(min(e|ing)|extract|resource|regolith|drill|ice|water)\b/i,
    action: (body) => `one small yellow toy rover slowly scooping a mound of dust from ${body}`,
  },
  {
    match: /\b(own|land|plot|property|claim|parcel|territor|buy|purchase)\b/i,
    action: (body) =>
      `a small striped surveyor flag being planted on ${body}, then gently tipping over and lifting away`,
  },
  {
    match: /\b(business|company|incorporat|invest|licen[cs]e|permit|register)\b/i,
    action: (body) =>
      `a small rocket lifting off from a blue Earth and arriving at ${body}, leaving a simple dotted arc behind it`,
  },
  {
    match: /\b(liab|collision|debris|damage|crash|insur)\b/i,
    action: () => "two small satellites drifting toward each other in orbit and gently bumping",
  },
  {
    match: /\b(launch|orbit|satellite|spacecraft|probe)\b/i,
    action: (body) => `one small satellite drifting slowly in orbit above ${body}`,
  },
]

const FALLBACK = (body: string) =>
  `one small astronaut floating slowly beside ${body}, turning gently`

/** The house style every scene is rendered in, whoever wrote the subject. */
function render(subject: string, setting: string): string {
  return [
    "Flat 2D vector cartoon animation, extremely simple, like a looping sticker.",
    `Scene: ${subject}.`,
    `Setting: ${setting}.`,
    "Heavy clean outlines, solid fills, bold readable silhouettes, gentle two-frame motion.",
    "One locked side view, centered, no camera movement, no cuts, seamless five-second loop.",
