    "no realistic textures, no gradients, no 3D rendering, no photorealism, no cinematic lighting.",
    "Depict only the physical activity. Never depict whether it is legal or illegal.",
  ].join(" ")
}

export function scenePrompt(question: string): string {
  const body = BODIES.find((b) => b.match.test(question)) ?? DEFAULT_BODY
  const activity = ACTIVITIES.find((a) => a.match.test(question))
  const subject = activity ? activity.action(body.name) : FALLBACK(body.name)
  return render(subject, `${body.look}, with a few tiny dot stars`)
}


const MODEL = process.env.OPENAI_MODEL ?? "gpt-4o-mini"

const SCENE_SYSTEM = `You describe one tiny animated scene for a space-law tool.

Given a question, name the PHYSICAL ACTIVITY it is about and where it happens, as one
